<script>
function brandKitEditor(form){return{form,tab:'basic',method:'manual',brief:'',draftMode:@js($kit?'missing':'complete'),mindIds:[],components:['palette','fonts','voice','taglines','bio','block_theme'],quote:null,estimated:0,busy:false,error:'',notice:'',assignmentLink:'',assignmentUrl:'',qrAssignment:'',qrAssignmentUrl:'',
 savedForm:JSON.stringify(form),initialHasErrors:@js($errors->any()),creatingShowcase:false,showcaseSections:@js(\App\Services\Brand\BrandKitShowcase::DEFAULTS),previewHtml:'',previewBusy:false,previewError:'',previewDevice:'phone',previewScale:1,previewHeight:634,previewSequence:0,previewTimer:null,
 initShowcase(){this.$watch('form',()=>this.queuePreview());this.$watch('showcaseSections',()=>this.queuePreview());this.$nextTick(()=>{if(this.$refs.previewStage){this.previewObserver=new ResizeObserver(()=>this.measurePreview());this.previewObserver.observe(this.$refs.previewStage);this.measurePreview();}this.updatePreview();});},
 destroy(){this.previewObserver?.disconnect();clearTimeout(this.previewTimer);},
 measurePreview(){if(this.$refs.previewStage){this.previewScale=Math.min(1,this.$refs.previewStage.clientWidth/(this.previewDevice==='phone'?390:960))||1;this.previewHeight=this.$refs.previewStage.clientHeight||634;}},
 queuePreview(){clearTimeout(this.previewTimer);this.previewTimer=setTimeout(()=>this.updatePreview(),500);},
 async updatePreview(){const url=@js(Route::has('user.brand-kits.showcase-preview')?route('user.brand-kits.showcase-preview'):null);if(!url)return;const sequence=++this.previewSequence;if(!this.showcaseSections.length){this.previewHtml='';this.previewError='Choose at least one public section.';return;}this.previewBusy=true;try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({kit_id:@js($kit?->id),form:this.form,sections:this.showcaseSections})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Could not update the preview.');if(sequence===this.previewSequence){this.previewHtml=data.html;this.previewError='';}}catch(e){if(sequence===this.previewSequence)this.previewError=e.message;}finally{if(sequence===this.previewSequence)this.previewBusy=false;}},
 pending:{},accepted:[],reviewNotes:'',
 applySuggestions(){for(const key of this.accepted)this.form[key]=this.pending[key];this.pending={};this.accepted=[];this.quote=null;this.notice='Suggestions added to your unsaved draft. Review and save when ready.'},
 fieldTab(name){if(['website','audience','tone','taglines','bio'].includes(name))return 'more';for(const [group,fields]of Object.entries(@js(\App\Services\Brand\BrandKitFields::GROUPS))){if(name in fields)return group==='identity'?'more':group;}if(['instructions','exclusions','block_theme'].includes(name))return 'advanced';return 'basic'},
 payload(){return{kit_id:@js($kit?->id),brief:(this.draftMode==='review'?'Review this saved brand for clarity, consistency, missing guidance and accessibility. Suggest concrete replacement text; do not invent facts or legal requirements. ':'')+this.brief+'\nCurrent draft: '+JSON.stringify(this.form),mind_ids:this.mindIds.map(Number),components:this.components}},
 async call(body){const r=await fetch(@js(route('user.brand-kits.draft')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.message||'Could not prepare draft.');return d},
 async estimate(){this.busy=true;this.error='';this.quote=null;try{const d=await this.call(this.payload());this.quote=d.quote;this.estimated=d.coins;}catch(e){this.error=e.message}finally{this.busy=false}},
 async generate(){if(this.busy||!this.quote)return;this.busy=true;this.error='';try{const d=await this.call({...this.payload(),quote:this.quote});const c=d.draft.config;this.reviewNotes=this.draftMode==='review'?(c.review_notes||''):'';const candidates={...Object.fromEntries(Object.keys(@js(\App\Services\Brand\BrandKitFields::text())).filter(k=>c[k]!==undefined).map(k=>[k,c[k]])),name:d.draft.name,description:c.description,audience:c.audience,instructions:c.instructions,exclusions:c.exclusions,primary:c.palette?.primary,secondary:c.palette?.secondary,accent:c.palette?.accent,heading:c.fonts?.heading,body:c.fonts?.body,tone:c.voice?.tone,taglines:c.taglines?.join('\n'),bio:c.bio,block_theme:c.block_theme};const group={description:'bio',audience:'bio',instructions:'voice',exclusions:'voice',primary:'palette',secondary:'palette',accent:'palette',heading:'fonts',body:'fonts',tone:'voice',taglines:'taglines',bio:'bio',block_theme:'block_theme'};this.pending={};this.accepted=[];for(const [key,value]of Object.entries(candidates)){if(value===undefined||value===null||String(value).trim()==='')continue;if(key==='name'&&this.draftMode==='selected')continue;if(group[key]&&!this.components.includes(group[key]))continue;if(this.draftMode==='missing'&&String(this.form[key]||'').trim())continue;if(String(value)!==String(this.form[key]||'')){this.pending[key]=value;this.accepted.push(key);}}this.notice='Draft ready · '+d.coins+' coins recorded. Select suggestions below. Your draft has not been changed yet.';}catch(e){this.error=e.message}finally{this.quote=null;this.busy=false}}
}}
</script>
@endsection
